import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷四·11","description":"易小帖 - 卷四·11","frontmatter":{"title":"卷四·11","description":"易小帖 - 卷四·11"},"headers":[],"relativePath":"zh/classics/yixiaotie/105.md","filePath":"zh/classics/yixiaotie/105.md"}'),o={name:"zh/classics/yixiaotie/105.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷四·11",tabindex:"-1"},[r("卷四·11 "),e("a",{class:"header-anchor",href:"#卷四·11","aria-label":"Permalink to “卷四·11”"},"​")],-1),e("p",null,"訟彖「剛來而得中」蜀才曰：此本遯卦，二進居三，三降居二，是以遯之九三來居訟之二，而適得其中。極是明白。來氏易謂：需與訟反對之卦，凡反對必有往來，訟之剛來而得中，謂需之五來而為訟之二也。案需訟二五皆陽爻也，亦皆中爻也。向使需五非陽而訟二陽則可雲剛來。需五非中，而訟二中，則可曰得中。今需訟對觀，以為剛則俱剛，以為中則俱中，何往何來？何得何失？訟可曰剛來得中，則需亦可曰剛來得中，是亂矣。來氏偶見漢儒言易與宋稍異，遂多襲漢說，而至於推易一法則，考求未得，遽以倒易法當之。烏知文王三易，又各有類乎。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
